#!/usr/bin/env bs
# shellcheck shell=bash
# tests/unit/testvar-schemaportableunit.sh — core/var-schema.sh (the generated metadata manifest) as POSIX code
# tests/unit/testvar-schemaportableunit.sh — core/var-schema.sh (сгенерированный манифест метаданных) как POSIX-код
#
# The manifest is generated by scripts/gen_var_schema.sh and holds one bs_var_declare call
# per annotated variable. It must parse in every shell and register the schemas after core/var.sh.
# Манифест генерируется scripts/gen_var_schema.sh и содержит по вызову bs_var_declare на каждую
# аннотированную переменную. Он обязан разбираться в любой оболочке и регистрировать схемы после core/var.sh.

set -euo pipefail

readonly TEST_SCRIPT_DIR="$(bs::script_dir)"
readonly BS_PROJECT_ROOT="$(cd "${TEST_SCRIPT_DIR}/../.." && pwd)"
readonly MODULE_SH="${BS_PROJECT_ROOT}/core/var-schema.sh"
# the files the probe sources, in dependency order / файлы, которые подключает проба, по порядку зависимостей
readonly PROBE_FILES=(bootstrap/shell.sh core/prereq.sh core/var.sh core/var-schema.sh)

source "${TEST_SCRIPT_DIR}/../testframework.sh"

T=""

probe() {
    local -r sh_bin="$1" snippet="$2"
    local f
    : > "${T}/probe.sh"
    for f in "${PROBE_FILES[@]}"; do
        printf 'BS_CURRENT_FILE="%s/%s"\n. "%s/%s"\n' "${BS_PROJECT_ROOT}" "${f}" "${BS_PROJECT_ROOT}" "${f}" >> "${T}/probe.sh"
    done
    printf '%s\n' "${snippet}" >> "${T}/probe.sh"
    env -i HOME="${T}/h" PATH="/usr/bin:/bin" "${sh_bin}" "${T}/probe.sh" 2>&1
}

eq() { testframework::assert_equal "$1" "$2" "$3" || true; }

test_parses_and_lints() {
    local sh_bin
    while IFS= read -r sh_bin; do
        testframework::assert_command "'${sh_bin}' -n '${MODULE_SH}'" "var-schema.sh parses in ${sh_bin##*/}" || true
    done < <(testframework::posix_shells)
    if utils::has shellcheck; then
        testframework::assert_command "shellcheck -s sh '${MODULE_SH}'" "shellcheck -s sh is clean for core/var-schema.sh" || true
    fi
    testframework::assert_command "grep -q '^# @shell posix' '${MODULE_SH}'" "core/var-schema.sh is declared @shell posix" || true
    testframework::assert_command "grep -q 'Generated by scripts/gen_var_schema.sh' '${MODULE_SH}'" "core/var-schema.sh is the generated manifest" || true
}

test_schemas() {
    local sh_bin sh_name
    while IFS= read -r sh_bin; do
        sh_name="${sh_bin##*/}"
        eq "type=int;ops=read" "$(probe "${sh_bin}" 'bs_var_schema E_SUCCESS')" "${sh_name}: E_SUCCESS schema"
        eq "type=bool;ops=read,write;default=false" "$(probe "${sh_bin}" 'bs_var_schema FRAMEWORK_DEBUG')" "${sh_name}: FRAMEWORK_DEBUG schema"
        eq "type=enum:auto|always|never;ops=read,write;default=auto;on_invalid=warn" "$(probe "${sh_bin}" 'bs_var_schema BS_LOG_COLOR')" "${sh_name}: BS_LOG_COLOR schema"
        eq "0 4" "$(probe "${sh_bin}" 'bs_var_validate BS_LOG_LEVEL DEBUG 2>/dev/null; printf "%s " "$?"; bs_var_validate BS_LOG_LEVEL BOGUS 2>/dev/null; printf "%s" "$?"')" "${sh_name}: BS_LOG_LEVEL enum validates"
        eq "rc=0" "$(probe "${sh_bin}" 'bs_var_declare E_SUCCESS "type=int;ops=read" 2>/dev/null; echo rc=$?')" "${sh_name}: re-declaring the same schema is idempotent"
    done < <(testframework::posix_shells)
}

main() {
    T="$(mktemp -d)"
    testframework::section "Parse and lint / Разбор и линт"; test_parses_and_lints
    testframework::section "Schemas / Схемы"; test_schemas
    rm -rf "${T:?}"
    testframework::summary
}

main "$@"
